const fs = require('fs')
const path = require('path')

const generator = path.join(__dirname, 'sync-client-system-text.cjs')
let source = fs.readFileSync(generator, 'utf8')
source = source.replace(
  'return `// Generated by ../shared-i18n/sync-client-system-text.cjs. Do not edit by hand.\\n${typeBlock}export const SYSTEM_TEXT_EN = Object.freeze(',
  'return `// Generated by ../shared-i18n/sync-client-system-text.cjs. Do not edit by hand.\\n${typeBlock}export const SYSTEM_TEXT_EN${typed ? ": Readonly<Record<string, string>>" : ""} = Object.freeze('
)
fs.writeFileSync(generator, source)
